import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

// Video 10 — Evaluation, narrated.
//
// Second runtime-dependent video. Scores experiment 13 (trained by
// Video 09 on support-faq) against the gold_dev dataset using the
// /evaluation/run-heldout endpoint. Eval handler dispatches to the
// QA handler because task_profile=instruction_sft. ~18s wall time
// for 20 samples on GB10.
//
// Durations come from tts/audio/v10-durations.json
// (generated by tts/generate_v10_narration.py).

const DURATIONS_PATH = path.resolve(
    __dirname,
    '../../tts/audio/v10-durations.json',
);

type Durations = {
    cold_open: number;
    setup: number;
    kickoff: number;
    watching: number;
    results: number;
    wrap: number;
};

const dur: Durations = JSON.parse(fs.readFileSync(DURATIONS_PATH, 'utf-8'));

const SCREENSHOT_DIR = 'docs-demo/screenshots';

async function padTo(
    page: import('@playwright/test').Page,
    sectionStartMs: number,
    sectionDurationSeconds: number,
) {
    const remaining = sectionDurationSeconds * 1000 - (Date.now() - sectionStartMs);
    if (remaining > 0) await page.waitForTimeout(remaining);
}

test('Video 10 — Evaluation narrated', async ({ page, request }) => {
    test.setTimeout(10 * 60_000);

    // ── Pre-roll: log in + acquire JWT ───────────────────────────────
    const loginResp = await request.post('http://localhost:8000/api/auth/local/login', {
        data: { username: 'admin', password: 'sk-mock-admin-key' },
    });
    expect(loginResp.ok()).toBeTruthy();
    const token = (await loginResp.json()).token as string;
    const authHeader = { Authorization: `Bearer ${token}` };

    await page.goto('/login');
    await page.getByPlaceholder('Enter your username').fill('admin');
    await page.getByPlaceholder('API Key or Password').fill('sk-mock-admin-key');
    await page.getByRole('button', { name: /^Sign in$/ }).click();
    await page.waitForURL((url) => url.pathname === '/', { timeout: 15_000 });

    await page
        .locator('[aria-label="Open the Demo · Support FAQ demo project"]')
        .click();
    await page.waitForURL(/\/project\/\d+\/pipeline\/data/, { timeout: 30_000 });

    const projectId = (page.url().match(/\/project\/(\d+)\//) || [])[1] ?? '';
    expect(projectId).not.toBe('');

    // Make sure the experiment from V09 still exists; bail with a
    // clear error if it doesn't.
    const expsResp = await request.get(
        `http://localhost:8000/api/projects/${projectId}/training/experiments`,
        { headers: authHeader },
    );
    const exps = (await expsResp.json()) as Array<{ id: number; name: string; status: string }>;
    const v09 = exps.find((e) => e.name === 'v09-narrated-run' && e.status === 'completed');
    expect(v09, 'V09 experiment must exist; run 09-training-run-narrated.spec.ts first').toBeTruthy();
    const experimentId = (v09 as { id: number }).id;

    // Navigate to the Evaluation tab — section starting point.
    await page.locator('button.tab[title="Evaluation"]').click();
    await page.waitForTimeout(1500);

    // ── Section: cold open ───────────────────────────────────────────
    let sectionStart = Date.now();
    await page.screenshot({ path: `${SCREENSHOT_DIR}/v10-eval-tab-before.png`, fullPage: true });
    await padTo(page, sectionStart, dur.cold_open);

    // ── Section: setup recap ─────────────────────────────────────────
    sectionStart = Date.now();
    // Hold on the eval tab. Nothing to click.
    await padTo(page, sectionStart, dur.setup);

    // ── Section: kickoff — POST /evaluation/run-heldout ──────────────
    // run-heldout blocks until the eval completes. Fire it and don't
    // await yet; let it run while sections 3+4 of audio play.
    sectionStart = Date.now();
    const evalPromise = request.post(
        `http://localhost:8000/api/projects/${projectId}/evaluation/run-heldout`,
        {
            headers: authHeader,
            data: {
                experiment_id: experimentId,
                dataset_name: 'gold_dev',
                eval_type: 'exact_match',
                max_samples: 20,
                max_new_tokens: 64,
                temperature: 0.0,
            },
            timeout: 5 * 60_000,
        },
    );
    await padTo(page, sectionStart, dur.kickoff);

    // ── Section: watching — block on eval completion ─────────────────
    sectionStart = Date.now();
    const evalResp = await evalPromise;
    expect(evalResp.ok()).toBeTruthy();
    const evalResult = await evalResp.json();
    // Eval is done. Reload the UI to land the metrics.
    await page.reload();
    await page.waitForTimeout(1500);
    await page.locator('button.tab[title="Evaluation"]').click();
    await page.waitForTimeout(1500);
    await padTo(page, sectionStart, dur.watching);

    // ── Section: results ────────────────────────────────────────────
    sectionStart = Date.now();
    await page.screenshot({ path: `${SCREENSHOT_DIR}/v10-eval-tab-after.png`, fullPage: true });
    console.log(
        `[v10] eval result id=${evalResult.id} ` +
            `exact_match=${evalResult.metrics?.exact_match} ` +
            `f1=${evalResult.metrics?.f1} ` +
            `pass_rate=${evalResult.pass_rate}`,
    );
    await padTo(page, sectionStart, dur.results);

    // ── Section: wrap ────────────────────────────────────────────────
    sectionStart = Date.now();
    await padTo(page, sectionStart, dur.wrap);
});
